def get_template_image(char_name):
    key = CHAR_TO_TEMPLATE.get(char_name, "K")
    b64 = CHARACTER_TEMPLATES.get(key, CHARACTER_TEMPLATES["DEFAULT"])
    try:
        data = base64.b64decode(b64)
        img = Image.open(io.BytesIO(data)).convert('RGB')
        return img
    except:
        return None

CACHE = OrderedDict()
def get_cache(uid):
    if uid in CACHE:
        ts,d = CACHE[uid]
        if time.time()-ts<300: return d
        del CACHE[uid]
    return None
def set_cache(uid,data):
    CACHE[uid]=(time.time(),data)
    if len(CACHE)>200: CACHE.popitem(last=False)

def safe_json(url,timeout=12):
    try:
        r=requests.get(url,headers={"User-Agent":"Mozilla/5.0"},timeout=timeout)
        if not r.text or r.text.strip().startswith("<"): return None
        if len(r.text.strip())<10: return None
        return r.json()
    except: return None

def parse_player(raw):
    if not raw: return None
    data=raw
    if isinstance(raw,dict) and "data" in raw and isinstance(raw["data"],dict):
        data=raw["data"]
    def find(keys,default="?"):
        for k in keys:
            if isinstance(data,dict) and k in data:
                v=data[k]
                if isinstance(v,(str,int,float)) and str(v).strip()!="": return v
            if isinstance(data,dict):
                for dk,dv in data.items():
                    if dk.lower()==k.lower():
                        if isinstance(dv,(str,int,float)) and str(dv).strip()!="": return dv
        def deep(o,d=0):
            if d>8: return None
            if isinstance(o,dict):
                for kk,vv in o.items():
                    if kk.lower() in [x.lower() for x in keys]:
                        if isinstance(vv,(str,int,float)) and str(vv).strip()!="":
                            return vv
                    r=deep(vv,d+1)
                    if r: return r
            elif isinstance(o,list):
                for it in o:
                    r=deep(it,d+1)
                    if r: return r
            return None
        r=deep(data)
        return r if r is not None else default
    nick=find(["nickname","accountName","playerName"],"Unknown")
    lvl=find(["level","AccountLevel"],"?" )
    likes=find(["liked","likes"],"?" )
    region=find(["region"],"IND")
    guild=find(["clanName","guildName","clan"],"No Guild")
    if not guild or str(guild).lower() in ["null","none"]: guild="No Guild"
    basic=data.get("basicInfo",{}) if isinstance(data,dict) else {}
    if isinstance(basic,dict):
        if nick=="Unknown": nick=basic.get("nickname",nick)
        if lvl=="?": lvl=basic.get("level",lvl)
        if likes=="?": likes=basic.get("liked",likes)
    clan=data.get("clanBasicInfo",{}) if isinstance(data,dict) else {}
    if isinstance(clan,dict) and guild=="No Guild":
        guild=clan.get("clanName",guild)
    return {"nickname":str(nick)[:20],"level":str(lvl),"likes":str(likes),"region":str(region),"guild":str(guild)[:20]}

def get_equip_with_ids(outfit,raw):
    items=[]
    def extract(obj):
        if isinstance(obj,dict):
            for k,v in obj.items():
                kl=k.lower()
                if kl in ["outfits","clothes","items","costumes","bundles","skins"]:
                    if isinstance(v,list):
                        for it in v:
                            if isinstance(it,dict):
                                iid=it.get("itemId") or it.get("id") or it.get("clothesId") or it.get("item_id")
                                name=it.get("name") or it.get("itemName") or it.get("displayName") or it.get("clothesName") or ""
                                if iid or name:
                                    items.append({"id":str(iid) if iid else "","name":str(name)[:22]})
                            elif isinstance(it,str) and len(it)>2:
                                items.append({"id":"","name":it[:22]})
                if isinstance(v,(dict,list)):
                    extract(v)
        elif isinstance(obj,list):
            for it in obj:
                extract(it)
    if outfit: extract(outfit)
    if raw: extract(raw)
    seen=set()
    uniq=[]
    for it in items:
        key=(it["id"]+it["name"]).lower()
        if key not in seen and it["name"] and len(it["name"])>2:
            if it["name"].lower() not in ["ind","sg","no guild","k","alok","unknown","none"]:
                seen.add(key)
                uniq.append(it)
    return uniq[:8]

def detect_char(raw,outfit):
    def find_id(o):
        if isinstance(o,dict):
            for k,v in o.items():
                if k.lower() in ["characterid","equippedcharacterid"]:
                    if str(v).isdigit(): return str(v)
                if isinstance(v,(dict,list)):
                    r=find_id(v)
                    if r: return r
        elif isinstance(o,list):
            for it in o:
                r=find_id(it)
                if r: return r
        return None
    cid=None
    if raw: cid=find_id(raw)
    if not cid and outfit: cid=find_id(outfit)
    if cid and cid in FF_CHAR_MAP: return FF_CHAR_MAP[cid],cid
    s=json.dumps(raw).lower() if raw else ""
    if outfit: s+=json.dumps(outfit).lower()
    for k,v in FF_CHAR_MAP.items():
        if v.lower() in s: return v,k
    return "K","8"

def get_player(uid):
    for url in [f"https://wzapi.vercel.app/get_all?uid={uid}&region=IND",f"https://wzapi.vercel.app/get?uid={uid}&region=IND",f"https://wzapi.vercel.app/get?uid={uid}&region=SG"]:
        d=safe_json(url,11)
        if d:
            ss=json.dumps(d).lower()
            if "player not found" in ss and len(ss)<800: continue
            if any(k in ss for k in ["nickname","basicinfo"]): return d
        time.sleep(0.2)
    return None

def get_outfit(uid):
    for url in [f"https://wzapi.vercel.app/outfit?uid={uid}&region=IND",f"https://wzapi.vercel.app/outfit?uid={uid}&region=SG"]:
        d=safe_json(url,9)
        if d and len(str(d))>30: return d
        time.sleep(0.15)
    return None

def get_ban(uid):
    cached=get_cache(uid)
    if cached: return cached
    for url in [f"https://wzapi.vercel.app/check_ban?uid={uid}",f"https://wzapiinfo.vercel.app/check_ban?uid={uid}"]:
        d=safe_json(url,8)
        if d:
            try:
                data=d.get("data",d) if isinstance(d,dict) else d
                if isinstance(data,dict):
                    ib=data.get("is_banned",data.get("banned"))
                    per=data.get("period",data.get("ban_period",0))
                    if ib is None and str(data.get("status","")).upper()=="OK": ib=False
                    if ib is not None:
                        banned=1 if str(ib).lower() in ["1","true","banned","yes"] else 0
                        if banned==0:
                            res=(0,per,"NOT BANNED",False)
                        else:
                            # Simple - only BANNED, no time
                            try:
                                p=int(str(per)) if per else 0
                                if p==0 or p>=9999 or p>3650:
                                    res=(1,per,"BANNED",True)
                                else:
                                    res=(1,per,"BANNED",True)
                            except:
                                res=(1,per,"BANNED",True)
                        set_cache(uid,res)
                        return res
            except: pass
        time.sleep(0.15)
    return (0,0,"NOT BANNED",False)

def generate_reference_image(player, equip_list, char):
    """FIXED: Square image, character fully visible, 8 hexagons with equipment names - NO EMPTY"""
    char_name=char[0] if isinstance(char,tuple) else str(char)
    base=get_template_image(char_name)
    if not base:
        base=Image.new('RGB',(1080,1080),(18,10,45))
    
    # Make SQUARE 1080x1080 - Telegram shows full, no crop
    W,H=1080,1080
    # Resize base to fit in square with character centered
    bw,bh=base.size
    # Crop base to square from center
    base_ratio=bw/bh
    if base_ratio>1:
        # wider than tall - crop width
        new_w=int(bh*1.0)
        left=(bw-new_w)//2
        base=base.crop((left,0,left+new_w,bh))
    base=base.resize((W,H),Image.Resampling.LANCZOS)
    
    img=base.copy()
    draw=ImageDraw.Draw(img,'RGBA')
    
    # Add dark vignette for equipment visibility
    # Top gradient dark
    for y in range(180):
        alpha=int(180*(1-y/180)*0.6)
        draw.line([(0,y),(W,y)],fill=(0,0,0,alpha))
    
    cx,cy=W//2,H//2+80
    
    # Hexagon positions - 8 around character, INSIDE safe area
    hex_size=58
    left_x=cx-320
    right_x=cx+320
    positions=[
        (left_x+70, cy-200),   # top left
        (left_x-20, cy-90),    # mid top left
        (left_x-20, cy+40),    # mid bottom left
        (left_x+70, cy+160),   # bottom left
        (right_x-70, cy-200),  # top right
        (right_x+20, cy-90),   # mid top right
        (right_x+20, cy+40),   # mid bottom right
        (right_x+70, cy+160),  # bottom right
    ]
    
    # Equipment emojis mapping
    def get_equip_icon(name):
        nl=name.lower()
        if any(x in nl for x in ["hair","wig","cap","hat","head"]): return "💇"
        if any(x in nl for x in ["mask","face"]): return "🎭"
        if any(x in nl for x in ["jacket","shirt","top","coat"]): return "🧥"
        if any(x in nl for x in ["pants","jeans","bottom"]): return "👖"
        if any(x in nl for x in ["shoe","boot","foot"]): return "👟"
        if any(x in nl for x in ["glove","hand"]): return "🧤"
        if any(x in nl for x in ["gun","mp40","ak47","m1014","awm","ump","scar","rifle","m1887"]): return "🔫"
        if any(x in nl for x in ["parachute","bag","backpack"]): return "🎒"
        if any(x in nl for x in ["beard","mustache"]): return "🧔"
        return "⭐"
    
    def draw_hexagon(center,size,item=None):
        x,y=center
        has_item=item is not None
        pts=[]
        for i in range(6):
            ang=math.radians(60*i-30)
            pts.append((x+size*math.cos(ang),y+size*math.sin(ang)))
        
        # Glow if has item
        if has_item:
            glow_pts=[]
            for i in range(6):
                ang=math.radians(60*i-30)
                glow_pts.append((x+(size+10)*math.cos(ang),y+(size+10)*math.sin(ang)))
            draw.polygon(glow_pts,fill=(140,70,255,40))
        
        # Hexagon
        outline_color=(140,70,255) if has_item else (70,35,110)
        draw.polygon(pts,fill=(30,15,60) if has_item else (20,10,35),outline=outline_color,width=3)
        
        # Inner highlight
        inner=[]
        for i in range(6):
            ang=math.radians(60*i-30)
            inner.append((x+size*0.68*math.cos(ang),y+size*0.68*math.sin(ang)))
        draw.polygon(inner,fill=(50,25,85,180) if has_item else (25,12,40,150))
        
        # Icon/Name inside
        if has_item and item:
            icon=get_equip_icon(item["name"])
            try:
                # Try bold font
                font=ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",26)
                font_small=ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",11)
            except:
                font=ImageFont.load_default()
                font_small=font
            
            # Icon emoji (as text)
            draw.text((x-14,y-20),icon,fill=(255,255,255),font=font)
            # Name truncated
            name=item["name"][:10]
            draw.text((x-len(name)*3,y+8),name,fill=(200,180,255),font=font_small)
    
    # Draw connections
    for idx,(hx,hy) in enumerate(positions):
        has_item=idx < len(equip_list)
        if has_item:
            draw.line([(hx,hy),(cx,cy)],fill=(120,70,200,90),width=2)
    
    # Draw hexagons - ALWAYS 8, with items if available else placeholder
    for idx,(hx,hy) in enumerate(positions):
        if idx < len(equip_list):
            draw_hexagon((hx,hy),hex_size,equip_list[idx])
        else:
            # Empty but still visible with ?
            draw_hexagon((hx,hy),hex_size,None)
            # Draw ? for empty
            try:
                font=ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",20)
            except:
                font=ImageFont.load_default()
            # Don't draw ? - leave empty but visible hexagon
    
    # If no equipment at all, show default 8 equipment slots
    if len(equip_list)==0:
        default_items=[{"name":"Hair"},{"name":"Mask"},{"name":"Jacket"},{"name":"Pants"},{"name":"Shoes"},{"name":"Gun"},{"name":"Parachute"},{"name":"Pet"}]
        for idx,(hx,hy) in enumerate(positions):
            if idx < len(default_items):
                draw_hexagon((hx,hy),hex_size,default_items[idx])
    
    return img

