async def handle_uid(update,context,uids,mode="info"):
    await context.bot.send_chat_action(chat_id=update.effective_chat.id,action=ChatAction.TYPING)
    status=await update.message.reply_text(f"🔍 Checking <code>{uids[0]}</code>...",parse_mode=ParseMode.HTML)
    for uid in uids[:1]:
        raw=get_player(uid)
        if not raw:
            await status.edit_text(f"❌ UID <code>{uid}</code> Not Found",parse_mode=ParseMode.HTML)
            return
        await status.edit_text(f"✅ Found! Creating image...",parse_mode=ParseMode.HTML)
        outfit=get_outfit(uid)
        ban=get_ban(uid)
        cname,cid=detect_char(raw,outfit)
        parsed=parse_player(raw)
        if not parsed: parsed={"nickname":"Unknown","level":"?","likes":"?","region":"IND","guild":"No Guild"}
        equip=get_equip_with_ids(outfit,raw)
        is_banned,per,ban_status,banned_bool=ban
        # Square image - no crop
        img=generate_reference_image(parsed,equip,(cname,cid))
        # Caption - SIMPLE BAN - no time
        if mode=="ban":
            if banned_bool:
                cap=f"<b>🔴 BAN CHECK 🔴</b>\n\n🆔 <code>{uid}</code> | 👤 {parsed['nickname']}\n⭐ Lv:{parsed['level']} | ❤️ {parsed['likes']} | 👥 {parsed['guild']}\n\n🚫 <b>{ban_status}</b>"
            else:
                cap=f"<b>🟢 BAN CHECK 🟢</b>\n\n🆔 <code>{uid}</code> | 👤 {parsed['nickname']}\n⭐ Lv:{parsed['level']} | ❤️ {parsed['likes']} | 👥 {parsed['guild']}\n\n✅ <b>{ban_status}</b>"
        else:
            ban_line=f"🚫 <b>{ban_status}</b>" if banned_bool else f"✅ <b>{ban_status}</b>"
            equip_txt=""
            if equip:
                equip_txt="\n\n🎒 <b>Equipment:</b>\n"
                for i,it in enumerate(equip[:8]):
                    equip_txt+=f"{'└' if i==len(equip[:8])-1 else '├'} {it['name']}\n"
            cap=f"<b>🟢 PLAYER INFO 🟢</b>\n\n🆔 <code>{uid}</code> | 👤 {parsed['nickname']}\n⭐ Level: {parsed['level']} | ❤️ Likes: {parsed['likes']}\n🌍 {parsed['region']} | 👥 Guild: {parsed['guild']}\n🎭 Character: {cname}\n\n{ban_line}{equip_txt}"
        try:
            if img:
                path=f"/tmp/ff_fixed_{uid}.jpg"
                img.save(path,"JPEG",quality=93)
                with open(path,'rb') as f:
                    await context.bot.send_photo(chat_id=update.effective_chat.id,photo=f,caption=cap,parse_mode=ParseMode.HTML,reply_markup=get_inline())
                await status.delete()
            else:
                await status.edit_text(cap,parse_mode=ParseMode.HTML,reply_markup=get_inline())
        except Exception as e:
            await status.edit_text(f"{cap}\nErr:{str(e)[:60]}",parse_mode=ParseMode.HTML,reply_markup=get_inline())

